const EventEmitter = require('events');

// Create a custom Radio Station
const myEmitter = new EventEmitter();

// 1. Setup Listeners (Tuning the radio)
// Listener 1: Send a welcome email
myEmitter.on('userRegistered', (user) => {
  console.log(`[Email Service]: Sending welcome email to ${user.name}`);
});

// Listener 2: Update analytics
myEmitter.on('userRegistered', (user) => {
  console.log(`[Analytics Service]: Incrementing total users stat.`);
});

// 2. Trigger the Event (Broadcasting the signal)
console.log("App running... user clicks register button.");

// Emitting triggers all listeners sequentially, passing the data object to them
myEmitter.emit('userRegistered', { id: 1, name: 'Alice' });
